  self.head = None

 def insert(self, node): 
  if self.head is None:
   self.head = node
  else:
   cur = self.head
   prev = cur
   while cur is not None: 
    if node.salary < cur.salary:
     if prev == cur:
      node.next = self.head
      self.head = node
     else:
      prev.next = node
      node.next = cur
      break
    else:
     prev = cur
     cur = cur.next
   else: 
    prev.next = node
