def convert_roman_to_int(roman_string):
    symbols = { 'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000 }
    result = 0
    max_num = 0
    for char in roman_string[::-1]:
        curr_num = symbols[char]
        if curr_num >= max_num:
            result += curr_num
        else:
            result -= curr_num
