    s1 = s1.replace(" ", "").lower()
    s2 = s2.replace(" ", "").lower()

    if len(s1) != len(s2):
        return False

    # Count the number of each character in the string
    count = {}
    for char in s1:
        if char not in count:
            count[char] = 1
        else:
            count[char] += 1

    # Check if the characters present in s2 too
